    function testFuzz_property(address from, uint256 v, bool useRevertingCallee) public {
        vm.assume(from != address(0));

        address[] memory tos = new address[](1);
        if (useRevertingCallee) {
            Reverter r = new Reverter();
            tos[0] = address(r);
        } else {
            Good g = new Good();
            tos[0] = address(g);
        }

        bool ok;
        try c.transfer(from, tos[0], tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        if (useRevertingCallee) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}

